import { useCallback, useContext } from "react";
import { languageContext } from "./languageContext";
import * as fr from "./translations/fr-json";
import * as es from "./translations/es-json";
import * as ja from "./translations/ja-json";
import * as de from "./translations/de-json";
import * as pl from "./translations/pl-json";
import * as ptBR from "./translations/pt-BR-json";
import * as nl from "./translations/nl-json";
import * as it from "./translations/it-json";
import * as zhHans from "./translations/zh-Hans-json";
import * as th from "./translations/th-json";
import * as id from "./translations/id-json";
import * as cs from "./translations/cs-json";
import * as sv from "./translations/sv-json";
import * as tr from "./translations/tr-json";
import * as ms from "./translations/ms-json";
import * as frFR from "./translations/fr-FR-json";
import * as en from "./translations/en-json";
import * as koKR from "./translations/ko-KR-json";
import * as zhTW from "./translations/zh-TW-json";
import * as daDK from "./translations/da-DK-json";
import * as fiFI from "./translations/fi-FI-json";
import * as huHU from "./translations/hu-HU-json";
import * as nbNO from "./translations/nb-NO-json";
import * as skSK from "./translations/sk-SK-json";
const dictionaries = new Map([
    ["en", en.translations],
    ["cs", cs.translations],
    ["de", de.translations],
    ["da-DK", daDK.translations],
    ["es", es.translations],
    ["fi-FI", fiFI.translations],
    ["fr-FR", frFR.translations],
    ["fr", fr.translations],
    ["hu-HU", huHU.translations],
    ["id", id.translations],
    ["it", it.translations],
    ["ja", ja.translations],
    ["ms", ms.translations],
    ["nb-NO", nbNO.translations],
    ["nl", nl.translations],
    ["pl", pl.translations],
    ["pt-BR", ptBR.translations],
    ["sk-SK", skSK.translations],
    ["sv", sv.translations],
    ["th", th.translations],
    ["tr", tr.translations],
    ["zh-Hans", zhHans.translations],
    ["ko-KR", koKR.translations],
    ["zh-TW", zhTW.translations]
]);
export const useLanguage = () => {
    const selectedLanguage = useContext(languageContext);
    const translate = useCallback((phrase) => {
        const dictionary = dictionaries.get(selectedLanguage) || {};
        return dictionary[phrase] || `**${phrase}`;
    }, [selectedLanguage]);
    return { translate };
};
